static TestProc c_init(const char*r){const char*a[]={"./darc","init",r,NULL};return test_exec(a,NULL);}
static TestProc c_snap(const char*r,const char*s,const char*ts,const char*name,const char*cfg){const char*a[18];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;if(cfg){a[n++]="--config";a[n++]=cfg;}a[n++]="snapshot";a[n++]="create";a[n++]=s;if(name){a[n++]="--name";a[n++]=name;}a[n++]="--timestamp";a[n++]=ts;a[n]=NULL;return test_exec(a,NULL);}
static TestProc c_del(const char*r,const char*sel,bool yes,bool dry){const char*a[10];int n=0;a[n++]="./darc";a[n++]="--repo";a[n++]=r;a[n++]="snapshot";a[n++]="delete";a[n++]=sel;if(yes)a[n++]="--yes";if(dry)a[n++]="--dry-run";a[n]=NULL;return test_exec(a,NULL);}
static size_t ref_count(const char*r){char*p=test_path(r,"refs/snapshots");DIR*d=p?opendir(p):NULL;size_t n=0;if(d){struct dirent*e;while((e=readdir(d)))if(e->d_name[0]!='.')n++;closedir(d);}free(p);return n;}
static bool ref_exists(const char*r,const char*h){char rel[128];snprintf(rel,sizeof rel,"refs/snapshots/%s",h);char*p=test_path(r,rel);bool ok=p&&access(p,F_OK)==0;free(p);return ok;}
static bool json_ok(const char*s){if(!s)return false;char e[256];size_t l=0,c=0;DarcValue*v=darc_json_parse((const uint8_t*)s,strlen(s),e,sizeof e,&l,&c);if(!v)return false;darc_value_free(v);return true;}
static int ncmp(const void*a,const void*b){return strcmp(*(char*const*)a,*(char*const*)b);}
static bool digest_rec(const char*root,const char*rel,DarcSha256*sh){char*dir=rel&&*rel?test_path(root,rel):strdup(root);if(!dir)return false;DIR*d=opendir(dir);if(!d){free(dir);return false;}char**v=NULL;size_t n=0;struct dirent*e;while((e=readdir(d)))if(strcmp(e->d_name,".")&&strcmp(e->d_name,"..")){char**q=realloc(v,(n+1)*sizeof*v);if(!q){closedir(d);free(dir);return false;}v=q;v[n++]=strdup(e->d_name);}closedir(d);if(n>1)qsort(v,n,sizeof*v,ncmp);bool ok=true;for(size_t i=0;i<n&&ok;i++){char*nr=rel&&*rel?test_path(rel,v[i]):strdup(v[i]);char*p=test_path(root,nr);struct stat st;if(!nr||!p||lstat(p,&st)){free(nr);free(p);ok=false;break;}uint64_t z=(uint64_t)strlen(nr);darc_sha256_update(sh,&z,sizeof z);darc_sha256_update(sh,nr,(size_t)z);uint32_t mt=(uint32_t)(st.st_mode&S_IFMT);darc_sha256_update(sh,&mt,sizeof mt);if(S_ISREG(st.st_mode)){DarcBuf b={0};if(test_read(p,&b))ok=false;else{z=(uint64_t)b.len;darc_sha256_update(sh,&z,sizeof z);darc_sha256_update(sh,b.data,b.len);darc_buf_free(&b);}}else if(S_ISDIR(st.st_mode))ok=digest_rec(root,nr,sh);free(nr);free(p);}for(size_t i=0;i<n;i++)free(v[i]);free(v);free(dir);return ok;}
static bool repo_digest(const char*r,uint8_t out[32]){DarcSha256 sh;darc_sha256_init(&sh);if(!digest_rec(r,"",&sh))return false;darc_sha256_final(&sh,out);return true;}
static void le64(uint8_t*p,uint64_t x){for(int i=0;i<8;i++)p[i]=(uint8_t)(x>>(8*i));}
static bool publish_ref(const char*r,const DarcCid*c){char h[65],rel[128],line[66];darc_cid_hex(c,h);snprintf(rel,sizeof rel,"refs/snapshots/%s",h);snprintf(line,sizeof line,"%s\n",h);char*p=test_path(r,rel);bool ok=p&&!test_write(p,line,65,0644);free(p);return ok;}
/* Find two valid SNAPSHOT objects sharing an 8-hex prefix, without weakening selector rules. */
static bool make_prefix_collision(const char*r,char prefix[9],DarcCid*out1,DarcCid*out2){DarcCid base;DarcSnapshotObj s={0};if(darc_resolve_snapshot(r,"HEAD",&base,&s))return false;darc_snapshot_free(&s);DarcObject o;if(darc_object_load(r,&base,&o,1)||o.type!=OBJ_SNAPSHOT)return false;DarcBuf p={0};bool ok=!darc_buf_put(&p,o.payload.data,o.payload.len);darc_object_free(&o);if(!ok||p.len<10){darc_buf_free(&p);return false;}enum{SZ=1<<19};uint32_t*keys=calloc(SZ,sizeof*keys),*vals=calloc(SZ,sizeof*vals);if(!keys||!vals){free(keys);free(vals);darc_buf_free(&p);return false;}uint32_t i1=0,i2=0,key=0;bool found=false;for(uint32_t i=1;i<=400000&&!found;i++){le64(p.data+2,(uint64_t)(9000000000000ULL+i));DarcCid c;darc_object_cid(OBJ_SNAPSHOT,p.data,p.len,&c);uint32_t k=((uint32_t)c.b[0]<<24)|((uint32_t)c.b[1]<<16)|((uint32_t)c.b[2]<<8)|c.b[3];size_t h=((uint64_t)k*2654435761u)&(SZ-1);while(vals[h]&&keys[h]!=k)h=(h+1)&(SZ-1);if(vals[h]){i1=vals[h];i2=i;key=k;found=true;}else{keys[h]=k;vals[h]=i;}}free(keys);free(vals);if(!found){darc_buf_free(&p);return false;}DarcConfig cfg;darc_config_defaults(&cfg);bool nw=false;uint64_t sb=0;le64(p.data+2,(uint64_t)(9000000000000ULL+i1));if(darc_object_store(r,OBJ_SNAPSHOT,p.data,p.len,&cfg,out1,&sb,&nw)){darc_config_free(&cfg);darc_buf_free(&p);return false;}le64(p.data+2,(uint64_t)(9000000000000ULL+i2));if(darc_object_store(r,OBJ_SNAPSHOT,p.data,p.len,&cfg,out2,&sb,&nw)){darc_config_free(&cfg);darc_buf_free(&p);return false;}darc_config_free(&cfg);darc_buf_free(&p);if(!publish_ref(r,out1)||!publish_ref(r,out2))return false;snprintf(prefix,9,"%08x",key);return true;}
static bool head_flat_file_chunk(const char*r,const char*path,DarcCid*out){DarcCid sid;DarcSnapshotObj s={0};DarcFlatTree t={0};if(darc_resolve_snapshot(r,"HEAD",&sid,&s)||darc_flatten_snapshot(r,&s,&t)){darc_snapshot_free(&s);return false;}DarcFlatEnt*e=darc_flat_find(&t,path);bool ok=false;if(e&&e->type==1){DarcObject o;DarcFileObj f={0};if(!darc_object_load(r,&e->cid,&o,1)&&o.type==OBJ_FILE&&!darc_file_parse(o.payload.data,o.payload.len,&f)&&f.chunk_n){*out=f.chunks[0].cid;ok=true;}darc_file_free(&f);darc_object_free(&o);}darc_flat_free(&t);darc_snapshot_free(&s);return ok;}
static bool object_exists(const char*r,const DarcCid*c){char*p=darc_object_path(r,c);bool ok=p&&access(p,F_OK)==0;free(p);return ok;}

