 {const char*a[]={"./darc","--version",NULL};x=test_exec(a,NULL);test_check("CLI-003",x.code==0&&test_contains(x.out,"darc 0.1.0"),"stable version string emitted");test_proc_free(&x);}
 {char*d=test_case_dir("cli004"),*r=test_path(d,"missing");const char*a[]={"./darc","--repo",r,"snapshot","list",NULL};x=test_exec(a,NULL);test_check("CLI-004",x.code==3&&test_contains(x.err,"E_REPO_NOT_FOUND"),"repo-required command maps missing repository to stable exit/code");test_proc_free(&x);free(r);free(d);}
 {const char*a[]={"./darc","--definitely-unknown",NULL};x=test_exec(a,NULL);test_check("CLI-005",x.code==2&&test_contains(x.err,"E_USAGE"),"unknown option rejected as usage error");test_proc_free(&x);}
 char*d=test_case_dir("cli-main"),*r=test_path(d,"repo"),*s=test_path(d,"src");test_mkdir(s);char*p=test_path(s,"a");test_write(p,"one",3,0644);x=c_init(r);test_proc_free(&x);x=c_snap(r,s,"1000000000","base",NULL);test_proc_free(&x);char base[65];test_head(r,base);
 {char pre[9];DarcCid a,b;bool made=make_prefix_collision(r,pre,&a,&b);const char*av[]={"./darc","--repo",r,"snapshot","show",pre,NULL};x=test_exec(av,NULL);test_check("CLI-006",made&&x.code==4&&test_contains(x.err,"E_SNAPSHOT_AMBIGUOUS"),"real pair of valid SNAPSHOT CIDs sharing eight hex digits is ambiguous");test_proc_free(&x);}
