 test_write(p,"two",3,0644);x=c_snap(r,s,"2000000000","dupname",NULL);test_proc_free(&x);test_write(p,"three",5,0644);x=c_snap(r,s,"3000000000","dupname",NULL);test_proc_free(&x);char head[65];test_head(r,head);
