 {const char*a[]={"./darc","--repo",r,"snapshot","show","HEAD",NULL};x=test_exec(a,NULL);test_check("CLI-009",x.code==0&&test_contains(x.out,head),"HEAD resolves to current published snapshot");test_proc_free(&x);}
 {char*sp=test_path(s,"pipe");mkfifo(sp,0644);char*cfg=test_path(d,"skip.json");const char*ct="{\"scan\":{\"on_special_file\":\"skip\"}}\n";test_write(cfg,ct,strlen(ct),0644);const char*a[]={"./darc","--repo",r,"--config",cfg,"--format","json","snapshot","create",s,"--timestamp","4000000000",NULL};x=test_exec(a,NULL);test_check("CLI-010",x.code==0&&json_ok(x.out)&&test_contains(x.err,"W_SCAN_SKIPPED"),"JSON stdout remains parseable while scanner warning/progress stays on stderr");test_proc_free(&x);unlink(sp);free(cfg);free(sp);}
 {const char*a[]={"./darc","--repo",r,"--quiet","snapshot","list",NULL};x=test_exec(a,NULL);test_check("CLI-011",x.code==0&&strlen(x.out)>20&&test_contains(x.out,"SNAPSHOT"),"quiet suppresses chatter but preserves required list data");test_proc_free(&x);}
 {DarcCid cc;bool got=head_flat_file_chunk(r,"src/a",&cc);char*op=got?darc_object_path(r,&cc):NULL;int fd=op?open(op,O_RDWR|O_CLOEXEC):-1;uint8_t z=0;bool bad=fd>=0&&pread(fd,&z,1,32)==1;if(bad){z^=0x44;bad=pwrite(fd,&z,1,32)==1&&fsync(fd)==0;}if(fd>=0)close(fd);const char*a[]={"./darc","--repo",r,"--format","json","verify","--level","full",NULL};x=test_exec(a,NULL);test_check("CLI-012",got&&bad&&x.code==6&&json_ok(x.out),"integrity exit code takes precedence while structured presentation remains valid");test_proc_free(&x);free(op);}
