 {const char*a[]={"./darc","--repo",r,"--format","json","snapshot","show","HEAD",NULL};x=test_exec(a,NULL);bool ok=x.code==0&&json_ok(x.out)&&test_contains(x.out,"\"id\"")&&test_contains(x.out,"\"created_ns\"")&&test_contains(x.out,"\"parent\"")&&test_contains(x.out,"\"root\"")&&test_contains(x.out,"\"files\"")&&test_contains(x.out,"\"logical_bytes\"")&&test_contains(x.out,"\"unique_chunks\"")&&test_contains(x.out,"\"new_stored_bytes\"")&&test_contains(x.out,"\"parity_stripes_active\"")&&test_contains(x.out,"\"profile_hash\"")&&test_contains(x.out,"\"sources\"");test_check("CLI-014",ok,"snapshot show exposes required identity, ancestry, Merkle, stats, parity/profile/source metadata");test_proc_free(&x);}
