 d=test_case_dir("del001");r=test_path(d,"repo");s=test_path(d,"src");test_mkdir(s);p=test_path(s,"a");x=c_init(r);test_proc_free(&x);char ids[3][65];for(int i=0;i<3;i++){char v[8],t[32];snprintf(v,sizeof v,"v%d",i);snprintf(t,sizeof t,"%d000000000",i+1);test_write(p,v,strlen(v),0644);x=c_snap(r,s,t,NULL,NULL);test_proc_free(&x);test_head(r,ids[i]);}size_t objs=test_count_objects(r,0),refs=ref_count(r);x=c_del(r,ids[1],true,false);test_check("DEL-001",x.code==0&&ref_count(r)==refs-1&&!ref_exists(r,ids[1])&&ref_exists(r,ids[0])&&ref_exists(r,ids[2])&&test_count_objects(r,0)==objs,"non-HEAD delete removes only target ref; canonical objects remain pre-GC");test_proc_free(&x);free(p);free(s);free(r);free(d);
